    ///  <span class="keyword">for</span> (<span class="keyword">auto</span> i <span class="operator">=</span> set<span class="operator">.</span>begin()<span class="operator">,</span> end <span class="operator">=</span> set<span class="operator">.</span>end(); i <span class="operator">!</span><span class="operator">=</span> end; <span class="operator">+</span><span class="operator">+</span>i)
